    g_run = 6; Prime(P(0, 0, 0)); Base(g_next, 4, 0); g_next.timers[2] = 7; g_next.make = true; RunPrimed();
    Expect("Reg1 Reg2 T1 T2 T3 Make T4 Dereg2 Dereg1 ");
